preConditionHook:
// THE EXPANDING TRIANGLE -- Brooks's broadening formation, read as a
// three-push pattern in which BOTH sides push further out: each swing high is
// above the swing high two pivots back AND each swing low is below the swing
// low two pivots back, over at least minLegs alternating pivots.
//
// NOT ThreePushPattern at shapeMode = 2, and this is the whole reason it is a
// separate file. ThreePushPattern tests ONE side per direction (its long is
// patDn, three lower swing lows; its short is patUp) and its shapeMode = 2
// compares the two INCREMENTS -- the later push extending MORE than the
// earlier one. This rule needs both sides diverging at once, which no single
// placement of ThreePushPattern can state (the per-placement negate toggle
// would give !patUp, not patUp itself), and it does not care whether the
// divergence accelerates. Hence identical sides: a broadening formation is a
// context, not a direction.
//
// THE PIVOT SCAN IS INLINED, verbatim from ThreePushPattern, rather than
// reaching into SwingHigh.json -- rules in this corpus never reference each
// other, and the register lists Occurrence 3 and above as UNMEASURED, so the
// third pivot would otherwise rest on an untested argument. The scan
// reproduces the MEASURED pivot rule (EL_Swing_Probe.txt /
// el_swing_output1.txt, @ES 60 min): the pivot bar is AT OR BEYOND the
// swingStrength OLDER bars and STRICTLY BEYOND the swingStrength NEWER bars
// (bars-ago indexing makes the SMALLER index the newer bar, so the strict
// half is the k < j loop, el_gt/el_lt, and the at-or-beyond half the k > j
// loop, el_ge/el_le); the confirmation lag is exactly swingStrength bars,
// which is why j starts there and never at 0; candidate offsets run
// 0..Length-1 inclusive so j stops at lookbackBars - 1, while the
// neighbourhood test reaches swingStrength bars PAST the window -- the
// deepest bar touched is lookbackBars - 1 + swingStrength; the comparisons
// carry the 2.22e-12 relational tolerance; the prices carry the -1 SENTINEL
// and every use is gated on the count reaching 3; the low side's tie sense is
// the mirror of the measured high-side rule. There is no WFSafe_SwingHigh in
// the MultiWalk library, so plain EL governs. Written WITHOUT an early break,
// matching the EL twin statement for statement -- Break is not a registered
// EasyLanguage word.
//
// nHiAll / nLoAll count EVERY pivot in the window while nHiPiv / nLoPiv cap
// at three for the price slots, so legCount is the pivot count the source's
// 'five or more legs' asks for. Counting all pivots in the window is the
// authoring decision for 'alternating pivots': the mixed pivot test already
// makes highs and lows interleave, and counting them separately would need an
// ordering test no source states.
//
// minExpansionTicks (Brooks default 0) is the margin by which each push must
// beat the one before it. It is written as a PAIR -- strictly beyond, AND at
// least minExpansionTicks ticks beyond -- so the default 0 keeps the strict
// 'above' the description asks for while a positive value means 'at least N
// ticks', not 'more than N'. The tick is ctx.MinMove() / ctx.PriceScale(),
// division-first, both VERIFIED and per-symbol constant for the run.
//
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration is a
// redefinition when this rule is placed twice in one strategy. Every one is
// fully assigned each bar before it is read.
tickSize = ctx.MinMove() / ctx.PriceScale();
pivS = (int)swingStrength;
pivW = (int)lookbackBars;
nHiPiv = 0;
nLoPiv = 0;
nHiAll = 0;
nLoAll = 0;
hiPx1 = -1.0;
hiPx2 = -1.0;
hiPx3 = -1.0;
loPx1 = -1.0;
loPx2 = -1.0;
loPx3 = -1.0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivS; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi) {
        nHiAll = nHiAll + 1;
        if (nHiPiv < 3) {
            nHiPiv = nHiPiv + 1;
            if (nHiPiv == 1) hiPx1 = high[j];
            if (nHiPiv == 2) hiPx2 = high[j];
            if (nHiPiv == 3) hiPx3 = high[j];
        }
    }
    if (okLo) {
        nLoAll = nLoAll + 1;
        if (nLoPiv < 3) {
            nLoPiv = nLoPiv + 1;
            if (nLoPiv == 1) loPx1 = low[j];
            if (nLoPiv == 2) loPx2 = low[j];
            if (nLoPiv == 3) loPx3 = low[j];
        }
    }
}
expHi = (nHiPiv == 3) && el_gt(hiPx1, hiPx2) && el_gt(hiPx2, hiPx3) && el_ge(hiPx1 - hiPx2, minExpansionTicks * tickSize) && el_ge(hiPx2 - hiPx3, minExpansionTicks * tickSize);
expLo = (nLoPiv == 3) && el_lt(loPx1, loPx2) && el_lt(loPx2, loPx3) && el_ge(loPx2 - loPx1, minExpansionTicks * tickSize) && el_ge(loPx3 - loPx2, minExpansionTicks * tickSize);
legCount = nHiAll + nLoAll;
isExpanding = expHi && expLo && ((double)legCount >= minLegs);
